B=Path('outputs/adaptive_crop_gate_v1');M=B/'metrics';F=B/'figures';R=Path('reports')
# j: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
# 입력 인수: p.
def j(p):return json.loads(Path(p).read_text())
# sha: 파일 바이트의 SHA-256을 계산해 입력 동일성 확인에 사용합니다.
# 입력 인수: p.
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
# savej: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
# 입력 인수: p, v.
def savej(p,v):Path(p).write_text(json.dumps(v,ensure_ascii=False,indent=2,default=lambda x:x.item() if isinstance(x,np.generic) else str(x)))
# table: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
# 입력 인수: d.
def table(d):
 # v: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
 # 입력 인수: x.
 def v(x):return 'NA' if pd.isna(x) else f'{x:.6g}' if isinstance(x,(float,np.floating)) else str(x).replace('|','/')
 return '\n'.join(['| '+' | '.join(d.columns)+' |','| '+' | '.join(['---']*len(d.columns))+' |']+['| '+' | '.join(v(x) for x in row)+' |' for row in d.itertuples(index=False,name=None)])
# summarize: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
# 입력 인수: d, keys.
def summarize(d,keys):
 out=[]
 for key,g in d.groupby(keys,dropna=False):
  key=key if isinstance(key,tuple) else (key,);p=g[g.original_pixels>0]
  out.append(dict(zip(keys,key))|dict(images=len(g),positive_masks=len(p),provided_masks=int(g.has_mask.sum()),retention=p.kept_pixels.sum()/p.original_pixels.sum() if len(p) else np.nan,removed=int(p.mask_state.eq('removed').sum()),partial=int(p.mask_state.eq('partial').sum()),preserved=int(p.mask_state.eq('preserved').sum()),mean_retention=p.retention.mean(),p05_retention=p.retention.quantile(.05),median_retention=p.retention.median(),min_retention=p.retention.min(),A_rate=g.selected_policy.eq('A').mean(),B_rate=g.selected_policy.eq('B').mean(),C_rate=g.selected_policy.eq('C').mean(),full_frame_rate=g.full_frame.mean(),side_mean=g.side.mean(),side_p05=g.side.quantile(.05),side_median=g.side.median(),side_p95=g.side.quantile(.95),magnification_mean=g.magnification.mean(),product_preservation_status='UNVERIFIED'))
 return pd.DataFrame(out)
